import bisect
import hashlib

def _pos(token: str) -> int:
    # stable across processes and languages; 128-bit then truncate is fine
    return int(hashlib.md5(token.encode()).hexdigest(), 16)

class ConsistentHash:
    def __init__(self, nodes=(), replicas: int = 200):
        self.replicas = replicas
        self.ring: list[int] = []          # sorted positions
        self.owner: dict[int, str] = {}     # position -> physical node
        for n in nodes:
            self.add(n)

    def add(self, node: str) -> None:
        for i in range(self.replicas):
            p = _pos(f'{node}#{i}')
            if p in self.owner:
                continue  # collision: skip, keeps ring sorted invariant
            self.owner[p] = node
            bisect.insort(self.ring, p)

    def remove(self, node: str) -> None:
        doomed = [p for p, o in self.owner.items() if o == node]
        for p in doomed:
            del self.owner[p]
            idx = bisect.bisect_left(self.ring, p)
            del self.ring[idx]

    def get(self, key: str) -> str:
        if not self.ring:
            raise KeyError('empty ring')
        p = _pos(key)
        idx = bisect.bisect(self.ring, p) % len(self.ring)  # wrap = clockwise
        return self.owner[self.ring[idx]]

    def get_n(self, key: str, n: int) -> list[str]:
        # replica set: first n *distinct* physical nodes clockwise
        if not self.ring:
            raise KeyError('empty ring')
        out, seen = [], set()
        p = _pos(key)
        idx = bisect.bisect(self.ring, p) % len(self.ring)
        for j in range(len(self.ring)):
            node = self.owner[self.ring[(idx + j) % len(self.ring)]]
            if node not in seen:
                seen.add(node)
                out.append(node)
                if len(out) == n:
                    break
        return out
